function ring(name, callback) {
  callback(new Error("busy"));
  callback(null, name + " answered");
}

function ringAsync(name) {
  return new Promise((resolve, reject) => {
    ring(name, (error, reply) => {
      console.log("callback ran");
      if (error) reject(error);
      else resolve(reply);
    });
  });
}

ringAsync("Ana").then(
  (reply) => console.log(reply),
  (error) => console.log("failed: " + error.message)
);
